  args.epilogue.thread.alpha=1.f; args.epilogue.thread.beta = CVOID?0.f:1.f;
  args.scheduler.raster_order = static_cast<decltype(args.scheduler.raster_order)>(RASTER);
  args.scheduler.max_swizzle_size = 1;
  Gemm g; if (g.can_implement(args)!=cutlass::Status::kSuccess) return 101;
  if (Gemm::get_workspace_size(args)>wsb) return 102;
