        if (gemm.can_implement(args) != cutlass::Status::kSuccess) return 101;
        if (Gemm::get_workspace_size(args) > ws_bytes) return 102;
        if (gemm.initialize(args, ws, s) != cutlass::Status::kSuccess) return 103;
